INSERT INTO public.knowledge_base (content, metadata, embedding, user_id) VALUES ('7) 
składanie wniosków o warunkowe zwolnienie i o odwołanie warunkowego 
zwolnienia; 
8) 
składanie wniosków o zarządzenie wykonania kary, której wykonanie 
warunkowo zawieszono, oraz o wykonanie kary zastępczej; 
9) 
składanie wniosków dotyczących wykonania kary ograniczenia wolności; 
9a) składanie wniosków o zawieszenie, podjęcie oraz o umorzenie postępowania 
wykonawczego; 
10) udzielanie pomocy postpenitencjarnej; 
11) udział w posiedzeniach sądu, w wypadkach wskazanych w ustawie; 
12) podejmowanie czynności mających na celu przygotowanie skazanego do 
zwolnienia z zakładu karnego; 
